use crate::aap::caps::{http_client, notifier};

struct Node;

/// Percent-encodes a string for use as a URL query value (RFC 3986 unreserved set kept).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch, granted by the platform team ahead of the graph update.
        // Its result is discarded and never reaches the output, so the output is
        // unchanged. A transport failure is a value and is ignored; a refusal by the
        // host allowlist traps at the boundary, as the http-client contract specifies.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let message = format!(
            "digest {}: {} considered",
            composed.date,
            composed.considered.len()
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
